package ai.nexus.voice;
import android.app.Activity;
import android.content.*;
import android.os.*;
import android.speech.*;
import android.speech.tts.*;
import ai.nexus.core.Text;
import java.util.*;

/** Foreground sessions only. No always-on recognizer, audio files or background service. */
public final class Voice {
    public interface Listener{void state(String state);void audio(float rms,String partial);void result(String text,boolean review);void error(String en,String fa);void utteranceDone();}
    private final Activity a;private final Listener l;private final Handler main=new Handler(Looper.getMainLooper());private SpeechRecognizer rec;private TextToSpeech tts;private boolean ready,closed;private int generation;private String last="",utterance="";public boolean listening,speaking;
    public Voice(Activity a,Listener l){this.a=a;this.l=l;tts=new TextToSpeech(a,status->{ready=status==TextToSpeech.SUCCESS&&!closed;});tts.setOnUtteranceProgressListener(new UtteranceProgressListener(){public void onStart(String id){}public void onDone(String id){finish(id,false);}public void onError(String id){finish(id,true);}});}
    private void finish(String id,boolean failed){main.post(()->{if(!closed&&id.equals(utterance)&&speaking){speaking=false;l.state("idle");if(failed)l.error("Speech engine could not play this voice.","موتور گفتار نتوانست این صدا را پخش کند.");else l.utteranceDone();}});}
    public void listen(String locale){stop();if(!SpeechRecognizer.isRecognitionAvailable(a)){l.error("No speech recognition service on this device. Use text or install a speech engine.","سرویس تشخیص گفتار نصب نشده است. متن وارد کنید یا موتور گفتار نصب کنید.");return;}int g=++generation;try{rec=SpeechRecognizer.createSpeechRecognizer(a);last="";rec.setRecognitionListener(new RecognitionListener(){private boolean live(){return generation==g&&!closed;}public void onReadyForSpeech(Bundle b){if(live())l.state("listening");}public void onBeginningOfSpeech(){}public void onRmsChanged(float r){if(live())l.audio(Math.max(0,Math.min(1,(r+2)/12f)),last);}public void onBufferReceived(byte[] b){}public void onEndOfSpeech(){if(live())l.state("transcribing");}public void onEvent(int i,Bundle b){}public void onPartialResults(Bundle b){if(!live())return;ArrayList<String> s=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);if(s!=null&&!s.isEmpty()){last=s.get(0);l.audio(.35f,last);}}public void onResults(Bundle b){if(!live())return;ArrayList<String> s=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);float[] f=b.getFloatArray(SpeechRecognizer.CONFIDENCE_SCORES);releaseRec();l.state("idle");if(s==null||s.isEmpty()){l.error("No speech recognized.","گفتاری تشخیص داده نشد.");return;}l.result(s.get(0),f==null||f.length==0||f[0]<.65f);}public void onError(int err){if(!live())return;releaseRec();l.state("idle");l.error("Recognition stopped ("+err+"). Check microphone, network and language support, or type a command.","تشخیص گفتار متوقف شد ("+err+"). میکروفون، شبکه و زبان را بررسی کنید یا متن بنویسید.");}});
        Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM).putExtra(RecognizerIntent.EXTRA_LANGUAGE,locale).putExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS,true).putExtra(RecognizerIntent.EXTRA_MAX_RESULTS,3);if(Build.VERSION.SDK_INT>=34){i.putExtra(RecognizerIntent.EXTRA_ENABLE_LANGUAGE_DETECTION,true);i.putExtra(RecognizerIntent.EXTRA_ENABLE_LANGUAGE_SWITCH,RecognizerIntent.LANGUAGE_SWITCH_BALANCED);i.putStringArrayListExtra(RecognizerIntent.EXTRA_LANGUAGE_DETECTION_ALLOWED_LANGUAGES,new ArrayList<>(Arrays.asList("fa-IR","en-US")));}listening=true;l.state("listening");rec.startListening(i);
        }catch(RuntimeException e){releaseRec();l.error("Recognition could not start.","تشخیص گفتار آغاز نشد.");}}
    private void releaseRec(){generation++;listening=false;if(rec!=null){rec.destroy();rec=null;}}
    public List<String> voices(String tag){List<String> out=new ArrayList<>();if(ready&&tts.getVoices()!=null)for(android.speech.tts.Voice v:tts.getVoices())if(v.getLocale().getLanguage().equals(Locale.forLanguageTag(tag).getLanguage()))out.add(v.getName());Collections.sort(out);return out;}
    public boolean speak(String text,String tag,String selected,float speed){stop();if(!ready||tts.setLanguage(Locale.forLanguageTag(tag))<0){l.error("No installed speaking voice for this language. The text result is ready.","صدای این زبان نصب نیست؛ نتیجهٔ متنی آماده است.");return false;}if(!selected.isEmpty()&&tts.getVoices()!=null)for(android.speech.tts.Voice v:tts.getVoices())if(v.getName().equals(selected))tts.setVoice(v);tts.setSpeechRate(speed);utterance=UUID.randomUUID().toString();speaking=tts.speak(Text.clipped(text,400),TextToSpeech.QUEUE_FLUSH,null,utterance)==TextToSpeech.SUCCESS;if(speaking)l.state("speaking");return speaking;}
    public void stop(){boolean was=listening||speaking;releaseRec();speaking=false;utterance="";if(tts!=null)tts.stop();if(was&&!closed)l.state("idle");}
    public void close(){closed=true;stop();if(tts!=null)tts.shutdown();}
}
